package com.rulecraft.decisionops.decisionapi.api;import com.rulecraft.decisionops.decisionapi.DecisionApiEvaluationService;import com.rulecraft.decisionops.decisionapi.DecisionApiEvaluationService.*;import com.rulecraft.decisionops.identity.security.CurrentUser;import java.util.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/projects/{projectId}/decision-services/{serviceId}/decision-api") public class DecisionApiWorkspaceController {private final DecisionApiEvaluationService service;public DecisionApiWorkspaceController(DecisionApiEvaluationService service){this.service=service;}@GetMapping("/requests")List<RequestView> history(@PathVariable UUID projectId,@PathVariable UUID serviceId,Authentication auth){return service.history(CurrentUser.require(auth),projectId,serviceId);}@PostMapping("/batches")BatchResponse batch(@PathVariable UUID projectId,@PathVariable UUID serviceId,@RequestBody BatchCommand body,Authentication auth){return service.batchSession(CurrentUser.require(auth),projectId,serviceId,body);}}
